{"implementation":"def solve(case):
    segments = case['payload']['segments']
    budget = case['payload']['budget']
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        return {'error': 'budget out of range', 'min_sum': min_sum, 'max_sum': cap_sum}
    allocations = [{'name': s['name'], 'tokens': s['minimum']} for s in segments]
    remaining = budget - min_sum
    # keep track of current tokens per segment for quick access
    alloc_dict = {s['name']: s['minimum'] for s in segments}
    cap_dict = {s['name']: s['capacity'] for s in segments}
    imp_dict = {s['name']: s['importance'] for s in segments}
    # original order for tie-breaking
    order = [s['name'] for s in segments]
    while remaining > 0:
        best_seg = None
        best_score = -1.0
        for name in order:
            if alloc_dict[name] < cap_dict[name]:
                # next position after current allocation
                next_pos = alloc_dict[name] + 1
                score = imp_dict[name] / next_pos
                if score > best_score:
                    best_score = score
                    best_seg = name
        if best_seg is None:
            # should not happen if budget <= cap_sum, but break to avoid infinite loop
            break
        alloc_dict[best_seg] += 1
        remaining -= 1
    # build result list in original order with updated tokens
    result_segments = []
    for s in segments:
        result_segments.append({'name': s['name'], 'tokens': alloc_dict[s['name']]})
    return {'segments': result_segments, 'total': budget}"}
